/bin/bash -lc "node --input-type=module <<'NODE'
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from 'node:net';
import { setTimeout as delay } from 'node:timers/promises';
import assert from 'node:assert/strict';
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const socket = createServer();
await new Promise(resolve => socket.listen(0, '127.0.0.1', resolve));
const port = socket.address().port;
await new Promise(resolve => socket.close(resolve));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'launch.sqlite') }, stdio: 'ignore' });
try {
  let healthy = false;
  for (let attempt = 0; attempt < 100; attempt++) {
    try {
      const response = await fetch("'`http://127.0.0.1:${port}/health`);
      assert.equal(response.status, 200);
      assert.deepEqual(await response.json(), { status: '"'ok' });
      healthy = true;
      break;
    } catch { await delay(25); }
  }
  assert.ok(healthy, 'npm start must launch a healthy server');
  console.log('npm start smoke check passed');
} finally {
  const exited = new Promise(resolve => child.once('exit', resolve));
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
NODE
"

